export function iconSvg(id){if(id==='brand')return brandSvg();const shapes=PATHS[id]||PATHS.LockKeyhole;return '<svg class="glyph" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'+shapes.map(([tag,attrs])=>'<'+tag+' '+Object.entries(attrs).map(([k,v])=>k+'="'+String(v).replaceAll('&','&amp;').replaceAll('"','&quot;')+'"').join(' ')+'/>').join('')+'</svg>';}
export function setIcon(el,id){const key=String(id);if(el.dataset.icon===key)return;el.innerHTML=iconSvg(id);el.dataset.icon=key;}
